import type { AppState, ColorMode } from './state';

/** ecliptic (x, y, z) -> scene (x, z, -y) so the ecliptic is the horizontal plane. */
function toScene(v: THREE.Vector3, x: number, y: number, z: number): THREE.Vector3 {
  return v.set(x, z, -y);
}

