  HTC: '#48c9b0', ETc: '#f1948a', JFc: '#82e0aa', JFC: '#f7dc6f',
  CTc: '#aab7b8', COM: '#85c1e9', PAR: '#76d7c4', HYP: '#bb8fce',
};
