        uColorMode: { value: 0 },
        uClassColors: { value: classes.map((c) => new THREE.Color(classColor(c))) },
        uDim: { value: 1 },
      },
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
    });
