  let downAt: { x: number; y: number } | null = null;
  const canvas = scene.renderer.domElement;
  canvas.addEventListener('pointermove', (ev) => {
    const r = canvas.getBoundingClientRect();
    pointer = { x: ev.clientX - r.left, y: ev.clientY - r.top };
    pointerMoved = true;
